import bisect
for z in range(int(input())):
	n = int(input())
	a = [int(x) for x in input().split()]
	b = []
	for i in range(n):
		j = bisect.bisect(b, a[i])
		if j == len(b):
			b.append(a[i])
		else:
			b[j] = a[i]
	for i in range(len(b)):
		b[i] = str(b[i])
	print(str(len(b)), ' '.join(b))
